template:
use std::collections::HashMap;

fn get_score(
    scores: &HashMap<String, i32>,
    name: &str,
) -> i32 {
    let score = scores.⟦lookup⟧;
    score.⟦unwrap_val⟧
}

fn main() {
    let mut map = HashMap::new();
    map.insert(String::from("Alice"), 100);
    println!("{}", get_score(&map, "Alice"));
}

tests:
#[test]
fn finds_existing_and_missing() {
    let mut map = HashMap::new();
    map.insert(String::from("Alice"), 100);
    assert_eq!(get_score(&map, "Alice"), 100);
    assert_eq!(get_score(&map, "Bob"), 0);
}
